package net.officefloor.hq.app.claim;

/** A claim as the screen sees it: the amount with two decimals, the date as yyyy-MM-dd, the status by name, the number (null when it has none), the due fixed on settling (null when it has none), who opened it (null when never opened), whether its person's last statement bound it, the figure it bound (null when it has none) the number a correction corrects (null for any other claim) and the date it is due by, as yyyy-MM-dd, its status log, oldest first (empty when not listed with it), and the date it was deferred to, as yyyy-MM-dd (null when never deferred), and how many proofs it has been given, and the number of the claim it was split off (null for any other claim), and the user whose open editor locks it (null when not locked), and whether it was added while its period was soft-closed, and the last day it was reminded, as yyyy-MM-dd (null when never reminded), and its external reference (null when it has none), and its tags, sorted (empty for none), and its comments, oldest first, as "user on date: text" (empty when not listed with them), and the number of the settle batch that settled it (null when none, or not listed with it), and its lines, in the order added, as "label qty x unit" (empty when not listed with them), and the sheet's today it last went to REVIEW, as yyyy-MM-dd (null when it never did, or not listed with it), and whether its late charge was waived. */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status,
        String number, String settledDue, String openedBy, boolean stated, String statedDue,
        String corrects, String dueBy, java.util.List<String> log, String deferredUntil, int proofs,
        String splitFrom, String lockedBy, boolean lateEntry, String remindedOn, String ref, java.util.List<String> tags,
        java.util.List<String> comments, Integer batch, java.util.List<String> lines, String reviewOn, boolean waived) {

    public static ClaimResponse from(Claim claim) {
        return from(claim, java.util.List.of());
    }

    public static ClaimResponse from(Claim claim, java.util.List<String> log) {
        return new ClaimResponse(claim.id(), claim.personId(), claim.amount().toPlainString(),
                claim.date().toString(), claim.note(), claim.status().name(), claim.number(),
                claim.settledDue() == null ? null : claim.settledDue().toPlainString(), claim.openedBy(), claim.stated(),
                claim.statedDue() == null ? null : claim.statedDue().toPlainString(), claim.corrects(),
                claim.dueBy().toString(), log,
                claim.deferredUntil() == null ? null : claim.deferredUntil().toString(), claim.proofs(),
                claim.splitFrom(), null, claim.lateEntry(),
                claim.remindedOn() == null ? null : claim.remindedOn().toString(), claim.ref(), claim.tags(),
                java.util.List.of(), null, java.util.List.of(), null, claim.waived());
    }

    /** The claim as locked by {@code user} (null: not locked). */
    public ClaimResponse withLockedBy(String user) {
        return new ClaimResponse(id, personId, amount, date, note, status, number, settledDue, openedBy, stated,
                statedDue, corrects, dueBy, log, deferredUntil, proofs, splitFrom, user, lateEntry, remindedOn, ref, tags, comments, batch, lines, reviewOn, waived);
    }

    /** The claim with its comments, oldest first. */
    public ClaimResponse withComments(java.util.List<String> comments) {
        return new ClaimResponse(id, personId, amount, date, note, status, number, settledDue, openedBy, stated,
                statedDue, corrects, dueBy, log, deferredUntil, proofs, splitFrom, lockedBy, lateEntry, remindedOn, ref, tags,
                comments, batch, lines, reviewOn, waived);
    }

    /** The claim with the number of the settle batch that settled it (null: none). */
    public ClaimResponse withBatch(Integer batch) {
        return new ClaimResponse(id, personId, amount, date, note, status, number, settledDue, openedBy, stated,
                statedDue, corrects, dueBy, log, deferredUntil, proofs, splitFrom, lockedBy, lateEntry, remindedOn, ref, tags,
                comments, batch, lines, reviewOn, waived);
    }

    /** The claim with its lines, in the order added, each "label qty x unit". */
    public ClaimResponse withLines(java.util.List<String> lines) {
        return new ClaimResponse(id, personId, amount, date, note, status, number, settledDue, openedBy, stated,
                statedDue, corrects, dueBy, log, deferredUntil, proofs, splitFrom, lockedBy, lateEntry, remindedOn, ref, tags,
                comments, batch, lines, reviewOn, waived);
    }

    /** The claim with the sheet's today it last went to REVIEW (null: never). */
    public ClaimResponse withReviewOn(java.time.LocalDate on) {
        return new ClaimResponse(id, personId, amount, date, note, status, number, settledDue, openedBy, stated,
                statedDue, corrects, dueBy, log, deferredUntil, proofs, splitFrom, lockedBy, lateEntry, remindedOn, ref, tags,
                comments, batch, lines, on == null ? null : on.toString(), waived);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A claim made by a person on a sheet. {@code amount} is 0.00 or more, in two decimals. {@code number}
 * is given when the claim is opened (null for a draft or a voided claim). {@code settledDue} is the due fixed
 * when it was settled (null when not settled, or settled while no rate of its grade applied on its date).
 * {@code openedBy} is the user who opened it (null when never opened). {@code stated} is whether its person's
 * last statement bound it, at {@code statedDue} (null when it had no figure then). A claim with a negative amount is a
 * correction: {@code corrects} is the number of the SETTLED claim of the same person it corrects (null for any other claim).
 * {@code dueBy} is fixed when the claim is made, the terms-th business day after its date (see {@code Holidays#dueBy}), and kept when its terms or its date change later; a holiday added later on or before it works it out again from its date with the terms it was fixed with (see {@code Claims#refixDueBys}).
 * {@code deferredUntil} is the date an OPEN claim was deferred to (null when never deferred).
 * {@code proofs} is how many proofs it has been given (0 for none).
 * {@code splitFrom} is the number of the claim it was split off (null for any other claim).
 * {@code lateEntry} is whether it was added while the period its due-by falls in was soft-closed.
 * {@code remindedOn} is the last sheet's today a reminder was written for it (null when never reminded).
 * {@code ref} is its external reference, unique on the sheet without regard to case (null when it has none).
 * {@code tags} are its tags, trimmed, lower-cased, without repeats and sorted (empty for none).
 * {@code waived} is whether a steward waived its late charge: it bears none from then on.
 */
public record Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
        ClaimStatus status, String number, BigDecimal settledDue, String openedBy, boolean stated,
        BigDecimal statedDue, String corrects, LocalDate dueBy, LocalDate deferredUntil, int proofs,
        String splitFrom, boolean lateEntry, LocalDate remindedOn, String ref, java.util.List<String> tags, boolean waived) {

    public Claim with(ClaimInput input, LocalDate date) {
        return new Claim(id, sheetId, personId, input.amount(), date, input.note(), status, number, settledDue, openedBy, stated, statedDue, input.corrects(), dueBy, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, input.ref(), input.tags(), waived);
    }

    public Claim withStatus(ClaimStatus status, String number, BigDecimal settledDue, String openedBy) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, ref, tags, waived);
    }

    /** The claim moved to another person: unbound from any statement, so live until their next one. */
    public Claim withPerson(long personId) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, false, null, corrects, dueBy, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, ref, tags, waived);
    }

    /** The claim re-dated to {@code date}, numbered {@code number}. */
    public Claim withDate(LocalDate date, String number) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, ref, tags, waived);
    }

    /** The claim deferred to {@code until}. */
    public Claim withDeferredUntil(LocalDate until) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, until, proofs, splitFrom, lateEntry, remindedOn, ref, tags, waived);
    }

    /** The claim with {@code amount} as its amount, unbound from any statement (live until its person's next one). */
    public Claim withAmountUnbound(BigDecimal amount) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, false, null, corrects, dueBy, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, ref, tags, waived);
    }

    /** The claim with {@code proofs} proofs. */
    public Claim withProofs(int proofs) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, ref, tags, waived);
    }

    /** The claim with its late charge waived. */
    public Claim withWaived() {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, ref, tags, true);
    }

    /** The claim reminded on {@code on}. */
    public Claim withRemindedOn(LocalDate on) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs, splitFrom, lateEntry, on, ref, tags, waived);
    }

    /**
     * Whether the claim is deferred on {@code today}: an OPEN claim deferred to a date the sheet's today has not reached
     * counts in no total, is not overdue, cannot be settled and is left unbound by a statement.
     */
    public boolean deferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && (today == null || today.isBefore(deferredUntil));
    }

    /** A correction: its due is its amount times the rate, with no floor and no late charge. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.history.AsOf;
